mapper.select:
SELECT max(tfm.ID) id, tfm.MIX_AREA, tfm.GLUE, GROUP_CONCAT( tlm.MACHINE_NAME ORDER BY tfm.machine_order SEPARATOR ',' ) AS MACHINE_NAME, GROUP_CONCAT( tfm.MACHINE_CODE ORDER BY tfm.machine_order SEPARATOR ',' ) AS MACHINE_CODE, GROUP_CONCAT( tfm.machine_order ORDER BY tfm.machine_order SEPARATOR ',' ) AS MACHINE_ORDER, max( tfm.remark ) remark, max( tfm.CREATE_TIME ) CREATE_TIME, max( tfm.del_flag ) del_flag, max( tfm.create_by ) create_by, max( tfm.update_by ) update_by, max( tfm.UPDATE_TIME ) UPDATE_TIME FROM t_formula_machine tfm inner join (select mix_area, machine_code, machine_name from t_mix_machine where del_flag = 0 union select mix_area, machine_code, machine_name from t_lhfl_machine where del_flag = 0) tlm on tfm.MIX_AREA=tlm.MIX_AREA and tfm.MACHINE_CODE=tlm.machine_code where tfm.del_flag = '0' and tfm.mix_area = #{mixArea} and INSTR(tfm.glue, #{glue}) > 0 GROUP BY tfm.MIX_AREA, tfm.GLUE
order by create_time desc
order by ${orderStr}

select MIX_AREA, GLUE from T_FORMULA_MACHINE where del_flag = '0' and ID in
#{id}
GROUP BY MIX_AREA, GLUE

mapper.insert:
insert into t_formula_machine
(id,mix_area,glue,machine_code,machine_order,remark,del_flag,create_by,create_time,update_by,update_time )
select NULL id, x.*
from (

    select
    #{formulaMachine.mixArea,jdbcType= VARCHAR} mix_area, #{formulaMachine.glue,jdbcType= VARCHAR} glue,
    #{formulaMachine.machineCode,jdbcType= VARCHAR} machine_code,#{formulaMachine.machineOrder,jdbcType=VARCHAR} machine_order, #{formulaMachine.remark,jdbcType= VARCHAR}
    remark, #{formulaMachine.delFlag,jdbcType= VARCHAR} del_flag, #{formulaMachine.createBy,jdbcType= VARCHAR}
    create_by, #{formulaMachine.createTime,jdbcType=TIMESTAMP} create_time,
    #{formulaMachine.updateBy,jdbcType= VARCHAR} update_by, #{formulaMachine.updateTime,jdbcType=TIMESTAMP}
    update_time 

) x

